data.personalAccounts??=[{id:'personal-demo',name:'Rafael Alves',email:'personal@forja.demo',limit:20}];data.licenseRequests??=[];data.studentAccounts??=[];data.students.forEach(s=>s.personalId??='personal-demo');save();
accounts.adm={email:'adm@forja.demo',name:'Administrador'};
function personalAccount(){return data.personalAccounts.find(p=>p.id===window.activePersonalId)||data.personalAccounts[0]}
function licenseUsage(id=window.activePersonalId){return data.students.filter(s=>s.personalId===id).length}
function hasLicense(){return licenseUsage()<personalAccount().limit}
function licensePanel(){const p=personalAccount(),used=licenseUsage(),pending=data.licenseRequests.some(r=>r.personalId===p.id&&r.status==='pendente');return `<section class="card license-panel"><div class="row"><div><span class="eyebrow">LICENÇAS DE ALUNOS</span><h2>${used} de ${p.limit} utilizadas</h2><p>${Math.max(0,p.limit-used)} cadastros disponíveis. Cada novo aluno utiliza uma licença.</p></div><button class="${hasLicense()?'':'primary'}" onclick="requestLicenses()" ${pending?'disabled':''}>${pending?'Solicitação aguardando ADM':'Solicitar +20 licenças'}</button></div><p class="note">Alunos já existentes também contam no limite. Novos lotes são liberados somente após aprovação do administrador.</p></section>`}
window.requestLicenses=()=>{if(role!=='personal')return;const id=window.activePersonalId;if(data.licenseRequests.some(r=>r.personalId===id&&r.status==='pendente')){toast('Você já tem uma solicitação pendente.');return}data.licenseRequests.push({id:crypto.randomUUID(),personalId:id,quantity:20,status:'pendente',created:new Date().toISOString()});save();render();toast('Solicitação de 20 licenças registrada para o ADM neste navegador.')};
window.resolveLicenses=(id,approve)=>{if(role!=='adm')return;const request=data.licenseRequests.find(r=>r.id===id);if(!request||request.status!=='pendente')return;const personal=data.personalAccounts.find(p=>p.id===request.personalId);if(!personal)return;if(approve)personal.limit+=20;request.status=approve?'aprovada':'recusada';request.resolved=new Date().toISOString();save();render();toast(approve?'20 licenças liberadas.':'Solicitação recusada.')};
async function passwordRecord(password,salt=Array.from(crypto.getRandomValues(new Uint8Array(16)))){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const result=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new Uint8Array(salt),iterations:100000,hash:'SHA-256'},key,256);return {salt,hash:Array.from(new Uint8Array(result)).map(x=>x.toString(16).padStart(2,'0')).join('')}}
async function checkPassword(password,record){return !!record&&(await passwordRecord(password,record.salt)).hash===record.hash}
function emailExists(email){return Object.values(accounts).some(a=>a.email===email)||data.personalAccounts.some(a=>a.email===email)||data.studentAccounts.some(a=>a.email===email)}
window.addStudent=()=>{if(role!=='personal')return;if(!hasLicense()){modal('<h2>Seu limite de alunos foi atingido.</h2><p>Solicite mais 20 licenças ao administrador para cadastrar novos alunos.</p><button class="primary" onclick="requestLicenses();document.querySelector(\'#modal\').close()">Solicitar +20 licenças</button>');return}modal(`<h2>Criar aluno e acesso</h2><form id="studentForm"><label>Nome<input name="name" required maxlength="80"></label><label>E-mail de acesso<input name="email" type="email" required autocomplete="off"></label><label>Senha fornecida pelo personal<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><p class="note">Use credenciais de teste. A senha não será exibida novamente; anote e forneça ao aluno.</p><label>Objetivo<select name="goal"><option>Hipertrofia</option><option>Condicionamento</option><option>Força</option></select></label><label>Nível<select name="level"><option>Iniciante</option><option>Intermediário</option><option>Avançado</option></select></label><fieldset><legend>Dias de treino da semana</legend><div class="schedule-days multiple-days">${weekdaysFull.map((day,i)=>`<label><input type="checkbox" name="days" value="${i}">${day}</label>`).join('')}</div></fieldset><p id="accountError" role="alert" hidden></p><button class="primary" id="createStudentButton">Criar aluno · usar 1 licença</button></form>`);$('#studentForm').onsubmit=async e=>{e.preventDefault();const form=e.target,f=new FormData(form),name=f.get('name').trim(),email=f.get('email').trim().toLowerCase(),password=f.get('password'),owner=window.activePersonalId,error=$('#accountError');const fail=message=>{error.hidden=false;error.textContent=message};if(!hasLicense()){fail('Limite atingido. Solicite mais 20 licenças.');return}if(!name||password.length<8){fail('Preencha o nome e use uma senha de pelo menos 8 caracteres.');return}if(emailExists(email)){fail('Este e-mail já está em uso.');return}$('#createStudentButton').disabled=true;try{const secret=await passwordRecord(password);if(role!=='personal'||owner!==window.activePersonalId||!hasLicense()||emailExists(email)){fail('Cadastro não concluído. Confira o limite e o e-mail.');return}let id=Date.now();while(data.students.some(s=>s.id===id))id++;const days=f.getAll('days').map(Number);data.students.push({id,name,goal:f.get('goal'),level:f.get('level'),personalId:owner});data.studentAccounts.push({student:id,email,password:secret});data.studentGoals[id]={water:2000,weekly:days.length||3,days,since:todayKey()};save();$('#modal').close();render();toast(`Aluno criado. Acesso: ${email}`)}catch{fail('Não foi possível criar o acesso. Tente novamente.')}finally{const button=$('#createStudentButton');if(button)button.disabled=false}}};
function adminScreen(){return heading('ADMINISTRAÇÃO · DEMONSTRAÇÃO','Licenças e solicitações.','Cada personal começa com 20 licenças. Aprove novos lotes de 20.',`<button class="primary" onclick="addPersonal()">+ Cadastrar personal</button>`)+`<div class="grid">${data.personalAccounts.map(p=>`<section class="card"><h2>${esc(p.name)}</h2><p>${esc(p.email)}</p><span class="tag">${licenseUsage(p.id)} / ${p.limit} LICENÇAS</span></section>`).join('')}</div><section class="card license-requests"><h2>Solicitações de mais 20 licenças</h2>${data.licenseRequests.slice().reverse().map(r=>`<div class="license-request"><div><b>${esc(data.personalAccounts.find(p=>p.id===r.personalId)?.name||'Personal')}</b><p>+20 licenças · ${new Date(r.created).toLocaleDateString('pt-BR')}</p></div><span class="tag">${r.status.toUpperCase()}</span>${r.status==='pendente'?`<button class="primary" onclick="resolveLicenses('${r.id}',true)">Aprovar +20</button><button onclick="resolveLicenses('${r.id}',false)">Recusar</button>`:''}</div>`).join('')||'<p>Nenhuma solicitação registrada.</p>'}<p class="note">Painel local de demonstração. Esta aprovação não constitui controle seguro de licenças no servidor.</p></section>`}
window.addPersonal=()=>{if(role!=='adm')return;modal('<h2>Novo personal · 20 licenças</h2><form id="personalForm"><label>Nome<input name="name" required maxlength="80"></label><label>E-mail<input type="email" name="email" required></label><label>Senha de teste<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><p id="personalError" role="alert" hidden></p><button class="primary">Cadastrar personal</button></form>');$('#personalForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),email=f.get('email').trim().toLowerCase(),name=f.get('name').trim(),password=f.get('password');if(emailExists(email)||!name||password.length<8){$('#personalError').hidden=false;$('#personalError').textContent='Confira os dados. O e-mail precisa ser único e a senha ter pelo menos 8 caracteres.';return}e.target.querySelector('button').disabled=true;const secret=await passwordRecord(password);if(role!=='adm'||emailExists(email))return;data.personalAccounts.push({id:crypto.randomUUID(),name,email,limit:20,password:secret});save();$('#modal').close();render();toast('Personal cadastrado com 20 licenças.') }};
const accountLogin=showLogin;showLogin=function(selected=loginRole){accountLogin(selected);$('.login-tabs').insertAdjacentHTML('beforeend',`<button role="tab" aria-selected="${selected==='adm'}" class="${selected==='adm'?'primary':''}" onclick="showLogin('adm')">Administrador</button>`);if(selected==='adm')$('#loginForm button.primary').textContent='Entrar como administrador ↗';$('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),email=f.get('email').trim().toLowerCase(),password=f.get('password'),error=$('#loginError');let identity=null;if(email===accounts[selected].email&&password==='forja123')identity={role:selected,personalId:'personal-demo',studentId:data.students.find(s=>s.id===1)?.id||data.students[0]?.id};else if(selected==='personal'){const a=data.personalAccounts.find(p=>p.email===email);if(a&&await checkPassword(password,a.password))identity={role:selected,personalId:a.id}}else if(selected==='aluno'){const a=data.studentAccounts.find(p=>p.email===email);if(a&&await checkPassword(password,a.password)){const s=data.students.find(s=>s.id===a.student);if(s)identity={role:selected,personalId:s.personalId,studentId:s.id}}}if(!identity){error.hidden=false;error.textContent='E-mail ou senha inválidos para este perfil.';return}sessionStorage.setItem('forja-identity',JSON.stringify(identity));sessionStorage.setItem('forja-session',selected);enterApp(selected)}};window.showLogin=showLogin;
const accountEnter=enterApp;enterApp=function(selected){let identity;try{identity=JSON.parse(sessionStorage.getItem('forja-identity'))}catch{}window.activePersonalId=identity?.personalId||'personal-demo';if(selected==='aluno'&&identity?.studentId)student=identity.studentId;accountEnter(selected);if(selected==='aluno'&&identity?.studentId){student=identity.studentId;render()}$('#role').value=selected;$('header .avatar').textContent=selected==='adm'?'AD':selected==='personal'?personalAccount().name.split(' ').map(x=>x[0]).slice(0,2).join(''):current().name.split(' ').map(x=>x[0]).slice(0,2).join('')};
$('#role').insertAdjacentHTML('beforeend','<option value="adm">Área do administrador</option>');const identityLogout=logoutButton.onclick;logoutButton.onclick=()=>{sessionStorage.removeItem('forja-identity');identityLogout()};
const scopedAppointments=appointmentsOn;appointmentsOn=key=>scopedAppointments(key).filter(a=>role!=='personal'||ownsStudent(a.student));const selectOwnStudent=window.selectStudent;window.selectStudent=id=>{if(role==='personal'&&!ownsStudent(id))return;if(role==='aluno'&&Number(id)!==student)return;selectOwnStudent(id)};
const scopeAppointmentEditor=window.editAppointment;window.editAppointment=id=>{if(!visibleStudents().length){toast('Cadastre um aluno primeiro.');return}scopeAppointmentEditor(id)};
const licensedRender=render;render=function(){if(role==='adm'){$('#nav').innerHTML='<button class="active" onclick="go(\'inicio\')">◫ Administração</button>';$('#content').innerHTML=adminScreen();appointmentDock.hidden=true;return}if(role==='personal'&&!ownsStudent(student))student=visibleStudents()[0]?.id||0;licensedRender();if(role==='personal'&&(page==='alunos'||page==='licencas')){if(page==='licencas')$('#content').innerHTML=heading('CONTROLE DE ACESSOS','Licenças dos seus alunos.','Cadastros e solicitações de expansão.');$('#content').insertAdjacentHTML('afterbegin',licensePanel());if(page==='alunos'){$('#content').insertAdjacentHTML('beforeend',`<section class="card student-access-list"><h2>Acessos fornecidos aos alunos</h2>${visibleStudents().map(s=>`<div class="listrow"><div><b>${esc(s.name)}</b><p>${esc(data.studentAccounts.find(a=>a.student===s.id)?.email||'Perfil existente · sem novo acesso cadastrado')}</p></div></div>`).join('')}</section>`)}}if(role==='personal')$('#nav').insertAdjacentHTML('beforeend',`<button class="${page==='licencas'?'active':''}" onclick="go('licencas')">♙ &nbsp; Licenças</button>`)};

